import { RepoKitError } from "../errors.js";
export class ForgeError extends RepoKitError {
    static errorCode = "forge.request_failed";
    constructor(message = "", options) {
        super(new.target.errorCode, message, options);
        this.name = new.target.name;
    }
}
export class ForgeCoverageError extends ForgeError {
    static errorCode = "forge.coverage_incomplete";
}
export class ForgeAuthError extends ForgeError {
    static errorCode = "forge.authentication_required";
}
export class ForgeNotFound extends ForgeError {
    static errorCode = "forge.not_found";
}
export class ForgeRateLimitError extends ForgeError {
    retryAfterMs;
    static errorCode = "forge.rate_limited";
    constructor(message, retryAfterMs) {
        super(message);
        this.retryAfterMs = retryAfterMs;
        this.name = "ForgeRateLimitError";
    }
}
export function isForgeRateLimitError(error) {
    // Installed extensions can resolve a separate copy of this package in the same process.
    return error instanceof Error && error.name === "ForgeRateLimitError" && "retryAfterMs" in error
        && typeof error.retryAfterMs === "number" && Number.isFinite(error.retryAfterMs) && error.retryAfterMs >= 0;
}
